:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-surface: #f5f5f5;
  --color-mist-rule: #e9e9e9;
  --color-ink: #141414;
  --color-frosted-glass: #ffffff1a;
  --color-pewter-veil: #d9d9d91a;
  --color-sunbeam-dot: #fecc33;
  --color-sprout-signal: #30a81d;
  --color-forest-play: #21935b;
  --color-ember-tick: #ff8400;

  /* Typography — Font Families */
  --font-swizzy: "Swizzy", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-pp-neue-montreal-mono: "PP Neue Montreal Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-arial: Arial, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 9px;
  --leading-small: 1;
  --tracking-small: 0.54px;
  --text-caption: 12px;
  --leading-caption: 1;
  --tracking-caption: 0.72px;
  --text-body-sm: 16px;
  --leading-body-sm: 1;
  --tracking-body-sm: 0px;
  --text-body: 24px;
  --leading-body: 1.1;
  --tracking-body: -0.48px;
  --text-subheading: 32px;
  --leading-subheading: 1;
  --tracking-subheading: -0.64px;
  --text-heading-sm: 38px;
  --leading-heading-sm: 1.16;
  --tracking-heading-sm: 0px;
  --text-heading: 58px;
  --leading-heading: 1.1;
  --tracking-heading: -1.16px;
  --text-display: 160px;
  --leading-display: 0.86;
  --tracking-display: -3.2px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-52: 52px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-100: 100px;
  --spacing-128: 128px;
  --spacing-180: 180px;

  /* Layout */
  --page-max-width: 1920px;
  --section-gap: 100px;
  --card-padding: 24px;
  --element-gap: 12px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --radius-2xl: 16px;
  --radius-3xl: 32px;
  --radius-3xl-2: 64px;
  --radius-full: 160px;

  /* Named Radii */
  --radius-buttons: 4px;
  --radius-cards: 16px;
  --radius-small-cards: 6px;
  --radius-images: 16px;
  --radius-inner-tiles: 0px;
  --radius-inputs: 32px;
  --radius-pills: 160px;
  --radius-tags: 160px;
  --radius-badges: 160px;
  --radius-avatars: 50%;
  --radius-small-elements: 2px;

  /* Shadows */
  --shadow-sm: rgba(172, 171, 171, 0.3) 0px -1px 10px 0px;
  --shadow-xl: rgba(0, 0, 0, 0.3) 0px 32px 68px 0px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-surface: #f5f5f5;
  --surface-mist-rule: #e9e9e9;
  --surface-frosted-glass: #ffffff1a;
  --surface-ink: #141414;
}

